    end

    def remove(id)
      gig = fetch(id)
      @gigs.delete(id)
      _emit(:removed, gig)
      gig
    end

    def gigs
      @gigs.values.sort_by { |g| [g.date, g.start_minute, g.id] }
    end

    def on_date(date)
      gigs.select { |g| g.date == date }
    end

    def total_fees
      @gigs.values.sum(&:fee_cents)
    end

